<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Falling Sand</title>
<style>
  :root {
    color-scheme: dark;
    --bg: #10131a;
    --panel: #191e29;
    --line: #30394a;
    --text: #eef3fa;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    display: grid;
    place-items: center;
    background: radial-gradient(circle at 50% 0%, #253047, var(--bg) 55%);
    color: var(--text);
    font: 15px system-ui, sans-serif;
  }
  main { width: min(94vw, 680px); text-align: center; }
  h1 { margin: 0 0 12px; font-size: 25px; letter-spacing: .08em; }
  canvas {
    width: min(94vw, 600px);
    height: min(94vw, 600px);
    display: block;
    margin: auto;
    background: #080b10;
    border: 2px solid #46516a;
    border-radius: 10px;
    box-shadow: 0 16px 50px #0009, inset 0 0 30px #0008;
    cursor: crosshair;
    image-rendering: pixelated;
    touch-action: none;
  }
  .controls {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 9px;
    margin: 15px 0;
  }
  button {
    border: 1px solid var(--line);
    border-radius: 9px;
    padding: 9px 13px;
    color: var(--text);
    background: var(--panel);
    cursor: pointer;
    font: inherit;
    transition: transform .12s, border-color .12s, background .12s;
  }
  button:hover { transform: translateY(-1px); border-color: #91a8d4; }
  button.active { outline: 2px solid #fff; outline-offset: 1px; }
  #mat-sand { background: #9c7134; }
  #mat-water { background: #246fba; }
  #mat-wall { background: #66707d; }
  #mat-acid { background: #4d9d37; }
  #mat-empty { background: #343a46; }
  #clear { background: #922f3a; }
  p { margin: 0 0 18px; color: #aeb8ca; }
</style>
</head>
<body>
<main>
  <h1>FALLING SAND</h1>
  <canvas id="sand" width="120" height="120" aria-label="Falling sand simulation"></canvas>
  <div class="controls">
    <button id="mat-sand" class="active">Sand</button>
    <button id="mat-water">Water</button>
    <button id="mat-wall">Wall</button>
    <button id="mat-acid">Acid</button>
    <button id="mat-empty">Eraser</button>
    <button id="clear">Clear</button>
  </div>
  <p>Drag on the sandbox to paint.</p>
</main>
<script>
(() => {
  const canvas = document.getElementById("sand");
  const ctx = canvas.getContext("2d");
  const w = 120, h = 120;
  const EMPTY = 0, SAND = 1, WATER = 2, WALL = 3, ACID = 4;
  const names = ["empty", "sand", "water", "wall", "acid"];
  const ids = { empty: EMPTY, sand: SAND, water: WATER, wall: WALL, acid: ACID };
  const colors = ["#080b10", "#d6a34b", "#3399e6", "#77818d", "#6ddd3e"];
  const grid = new Uint8Array(w * h);
  const moved = new Uint8Array(w * h);
  let selected = SAND, painting = false;

  const index = (x, y) => y * w + x;
  const inside = (x, y) => x >= 0 && x < w && y >= 0 && y < h;
  const cell = (x, y) => inside(x, y) ? grid[index(x, y)] : WALL;
  const randOrder = () => Math.random() < .5 ? [-1, 1] : [1, -1];

  function move(from, to) {
    grid[to] = grid[from];
    grid[from] = EMPTY;
    moved[to] = 1;
  }

  // A sinking grain pushes liquid sideways at the contact point, rather than
  // lifting it upward through the falling column.
  function sinkSand(x, y, below) {
    const dirs = randOrder();
    for (const dx of dirs) {
      const side = index(x + dx, y + 1);
      if (x + dx > 0 && x + dx < w - 1 && grid[side] === EMPTY) {
        grid[side] = grid[below];
        moved[side] = 1;
        move(index(x, y), below);
        return true;
      }
    }
    return false;
  }

  function stepLiquid(x, y, type) {
    const here = index(x, y);
    const down = index(x, y + 1);
    if (y < h - 1 && grid[down] === EMPTY) { move(here, down); return; }

    const dirs = randOrder();
    for (const dx of dirs) {
      const nx = x + dx, ny = y + 1;
      if (nx > 0 && nx < w - 1 && ny < h && grid[index(nx, ny)] === EMPTY) {
        move(here, index(nx, ny)); return;
      }
    }
    for (const dx of dirs) {
      const nx = x + dx;
      if (nx > 0 && nx < w - 1 && grid[index(nx, y)] === EMPTY) {
        move(here, index(nx, y)); return;
      }
    }
  }

  function stepAcid(x, y) {
    const dirs = randOrder();
    const targets = [[x, y + 1], [x + dirs[0], y], [x + dirs[1], y]];
    for (const [tx, ty] of targets) {
      if (inside(tx, ty) && ty < h - 1) {
        const t = index(tx, ty);
        if (grid[t] === SAND || grid[t] === WALL) {
          grid[t] = EMPTY;
          if (Math.random() < .13) { grid[index(x, y)] = EMPTY; return; }
          break;
        }
      }
    }
    stepLiquid(x, y, ACID);
  }

  function tick(n = 1) {
    n = Math.max(0, Math.floor(Number(n) || 0));
    while (n--) {
      moved.fill(0);
      for (let y = h - 1; y >= 0; y--) {
        for (let x = 0; x < w; x++) {
          const i = index(x, y), type = grid[i];
          if (moved[i] || type === EMPTY || type === WALL) continue;
          if (type === SAND) {
            if (y < h - 1) {
              const down = index(x, y + 1);
              if (grid[down] === EMPTY) move(i, down);
              else if (grid[down] === WATER || grid[down] === ACID) sinkSand(x, y, down);
              else {
                for (const dx of randOrder()) {
                  const nx = x + dx, ny = y + 1;
                  if (nx > 0 && nx < w - 1 && grid[index(nx, ny)] === EMPTY) {
                    move(i, index(nx, ny)); break;
                  }
                }
              }
            }
          } else if (type === WATER) {
            stepLiquid(x, y, type);
          } else if (type === ACID) {
            stepAcid(x, y);
          }
        }
      }
    }
    render();
  }

  function render() {
    const image = ctx.createImageData(w, h);
    for (let i = 0; i < grid.length; i++) {
      const hex = colors[grid[i]];
      const r = parseInt(hex.slice(1, 3), 16);
      const g = parseInt(hex.slice(3, 5), 16);
      const b = parseInt(hex.slice(5, 7), 16);
      image.data[i * 4] = r;
      image.data[i * 4 + 1] = g;
      image.data[i * 4 + 2] = b;
      image.data[i * 4 + 3] = 255;
    }
    ctx.putImageData(image, 0, 0);
  }

  function clear() { grid.fill(EMPTY); render(); }
  window.sim = {
    w, h,
    tick,
    get(x, y) { return inside(x, y) ? names[grid[index(x, y)]] : "wall"; },
    set(x, y, material) {
      if (inside(x, y) && Object.prototype.hasOwnProperty.call(ids, material)) {
        grid[index(x, y)] = ids[material];
        render();
      }
    },
    clear
  };

  function paint(event) {
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((event.clientX - rect.left) * w / rect.width);
    const y = Math.floor((event.clientY - rect.top) * h / rect.height);
    if (!inside(x, y)) return;
    for (let yy = y - 1; yy <= y + 1; yy++) {
      for (let xx = x - 1; xx <= x + 1; xx++) {
        if (inside(xx, yy)) grid[index(xx, yy)] = selected;
      }
    }
    render();
  }

  canvas.addEventListener("pointerdown", e => {
    painting = true; canvas.setPointerCapture(e.pointerId); paint(e);
  });
  canvas.addEventListener("pointermove", e => { if (painting) paint(e); });
  canvas.addEventListener("pointerup", () => painting = false);
  canvas.addEventListener("pointercancel", () => painting = false);

  document.querySelectorAll("[id^='mat-']").forEach(button => {
    button.addEventListener("click", () => {
      selected = ids[button.id.slice(4)];
      document.querySelectorAll("[id^='mat-']").forEach(b => b.classList.remove("active"));
      button.classList.add("active");
    });
  });
  document.getElementById("clear").addEventListener("click", clear);

  let last = 0;
  function animate(now) {
    if (now - last > 33) { tick(1); last = now; }
    requestAnimationFrame(animate);
  }
  render();
  requestAnimationFrame(animate);
})();
</script>
</body>
</html>
